583|+CREATE OR REPLACE FUNCTION core.create_encrypted_run(
584|+  p_run jsonb,p_user_id uuid,p_owner_ref uuid,p_battery_rows jsonb
585|+)
586|+RETURNS boolean
587|+LANGUAGE plpgsql
588|+VOLATILE
589|+SECURITY DEFINER
590|+SET search_path = pg_catalog
591|+AS $$
592|+DECLARE
593|+  v_run_id uuid;
594|+  v_execution_ref uuid;
595|+  v_battery_row jsonb;
596|+BEGIN
597|+  IF jsonb_typeof(p_run)<>'object' OR p_run-ARRAY[
598|+    'runId','questionLine','askerId','executionRef','callerScope','asOf',
599|+    'askerRiskTier','riskTier','tierSource','tierProvenanceRef',
600|+    'compositionBudgetTier','planTier','depthParams','discoveredPanel','strangerSampleRate',
601|+    'envelopeBasis','registerVersion','batteryVersion','askContract',
602|+    'contentCiphertext','contentAttestation','contentAttestationSecret'
603|+  ]::text[]<>'{}'::jsonb
604|+    OR jsonb_typeof(p_battery_rows)<>'array'
605|+    OR jsonb_array_length(p_battery_rows)>100 THEN
606|+    RETURN false;
607|+  END IF;
608|+  v_run_id := (p_run->>'runId')::uuid;
609|+  v_execution_ref := (p_run->>'executionRef')::uuid;
610|+  IF p_run->>'questionLine'<>'⟦DEBATEAI:CIPHERTEXT:V1⟧'
611|+    OR p_run->>'askerId'<>'owner:'||p_owner_ref::text
612|+    OR p_run->'askContract'<>'{"ciphertext":true,"v":1}'::jsonb
613|+    OR NOT core.lock_run_key_provision_for_commit(
614|+      v_run_id,p_user_id,p_owner_ref,v_execution_ref
615|+    ) THEN
616|+    RETURN false;
617|+  END IF;
618|+  IF octet_length(decode(p_run->>'contentAttestationSecret','base64'))<>32
619|+    OR octet_length(decode(p_run->>'contentAttestation','base64'))<>32 THEN
620|+    RETURN false;
621|+  END IF;
622|+  FOR v_battery_row IN SELECT value FROM jsonb_array_elements(p_battery_rows)
623|+  LOOP
624|+    IF jsonb_typeof(v_battery_row)<>'object' OR v_battery_row-ARRAY[
625|+      'batteryRowId','predicateRef','openingState','predicateInputs','skipEvidence'
626|+    ]::text[]<>'{}'::jsonb THEN
627|+      RETURN false;
628|+    END IF;
629|+  END LOOP;
630|+  INSERT INTO core.run_content_attestation_secret(run_id,secret,created_at)
631|+  VALUES (v_run_id,decode(p_run->>'contentAttestationSecret','base64'),clock_timestamp());
632|+  INSERT INTO core.run(
633|+    run_id,question_line,asker_id,session_id,caller_scope,as_of,
634|+    asker_risk_tier,risk_tier,tier_source,tier_provenance_ref,
635|+    composition_budget_tier,plan_tier,depth_params,agent_count,discovered_panel,
636|+    stranger_sample_rate,envelope_basis,register_version,battery_version,
637|+    ask_contract,created_at_seq,content_encryption_version,
638|+    question_blind_index_version,question_blind_index,content_ciphertext,content_attestation
639|+  ) VALUES (
640|+    v_run_id,p_run->>'questionLine',p_run->>'askerId',v_execution_ref::text,
641|+    p_run->>'callerScope',(p_run->>'asOf')::timestamptz,
642|+    p_run->>'askerRiskTier',p_run->>'riskTier',p_run->>'tierSource',
643|+    p_run->>'tierProvenanceRef',p_run->>'compositionBudgetTier',p_run->>'planTier',
644|+    p_run->'depthParams',jsonb_array_length(p_run->'discoveredPanel'),
645|+    p_run->'discoveredPanel',(p_run->>'strangerSampleRate')::double precision,
646|+    p_run->'envelopeBasis',(p_run->>'registerVersion')::bigint,
647|+    p_run->>'batteryVersion',p_run->'askContract',ledger.allocate_sequence(),
648|+    1,2,NULL,p_run->'contentCiphertext',decode(p_run->>'contentAttestation','base64')
649|+  );
650|+  PERFORM core.append_run_ownership_event(v_run_id,p_owner_ref);
651|+  INSERT INTO core.question_liveness_event(run_id,kind,occurred_at,at_seq)
652|+  VALUES (v_run_id,'QUERY',clock_timestamp(),ledger.allocate_sequence());
653|+  INSERT INTO core.run_progress_event(run_id,at_seq,kind,value_json) VALUES
654|+    (v_run_id,ledger.allocate_sequence(),'PHASE',to_jsonb('EMPIRICAL'::text)),
655|+    (v_run_id,ledger.allocate_sequence(),'ENVELOPE_STATE',to_jsonb('WITHIN'::text)),
656|+    (v_run_id,ledger.allocate_sequence(),'ENVELOPE_CONSUMED',to_jsonb(0));
657|+  FOR v_battery_row IN SELECT value FROM jsonb_array_elements(p_battery_rows)
658|+  LOOP
659|+    INSERT INTO core.run_row_activation(run_id,battery_row_id,predicate_ref)
660|+    VALUES (v_run_id,v_battery_row->>'batteryRowId',v_battery_row->>'predicateRef');
661|+    INSERT INTO core.run_row_activation_event(
662|+      run_id,battery_row_id,at_seq,state,predicate_inputs,skip_evidence
663|+    ) VALUES (
664|+      v_run_id,v_battery_row->>'batteryRowId',ledger.allocate_sequence(),
665|+      v_battery_row->>'openingState',v_battery_row->'predicateInputs',
666|+      CASE WHEN jsonb_typeof(v_battery_row->'skipEvidence')='null'
667|+        THEN NULL ELSE v_battery_row->'skipEvidence' END
668|+    );
669|+  END LOOP;
670|+  IF NOT core.complete_run_key_provision(
671|+    v_run_id,p_user_id,p_owner_ref,v_execution_ref
672|+  ) THEN
673|+    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='RUN_KEY_PROVISION_INTENT_INCOMPLETE';
674|+  END IF;
675|+  RETURN true;
676|+EXCEPTION WHEN invalid_text_representation OR check_violation OR not_null_violation THEN
677|+  RETURN false;
678|+END;
679|+$$;
