1016|+function closingDelimiter(
1017|+  source: string,
1018|+  openingIndex: number,
1019|+  opening: "(" | "{",
1020|+  closing: ")" | "}"
1021|+): number {
1022|+  let depth = 0;
1023|+  let quote: '"' | "'" | "`" | undefined;
1024|+
1025|+  for (let index = openingIndex; index < source.length; index += 1) {
1026|+    const character = source[index]!;
1027|+    const next = source[index + 1];
1028|+    if (quote) {
1029|+      if (character === "\\") index += 1;
1030|+      else if (character === quote) quote = undefined;
1031|+      continue;
1032|+    }
1033|+    if (character === "/" && next === "/") {
1034|+      index = source.indexOf("\n", index + 2);
1035|+      if (index === -1) return source.length;
1036|+      continue;
1037|+    }
1038|+    if (character === "/" && next === "*") {
1039|+      index = source.indexOf("*/", index + 2);
1040|+      if (index === -1) return source.length;
1041|+      index += 1;
1042|+      continue;
1043|+    }
1044|+    if (character === '"' || character === "'" || character === "`") {
1045|+      quote = character;
1046|+      continue;
1047|+    }
1048|+    if (character === opening) depth += 1;
1049|+    if (character === closing) {
1050|+      depth -= 1;
1051|+      if (depth === 0) return index;
1052|+    }
1053|+  }
1054|+
1055|+  return source.length;
