1058|+function skipTrivia(source: string, start: number): number {
1059|+  let index = start;
1060|+  while (index < source.length) {
1061|+    if (/\s/.test(source[index]!)) {
1062|+      index += 1;
1063|+    } else if (source.startsWith("//", index)) {
1064|+      const newline = source.indexOf("\n", index + 2);
1065|+      index = newline === -1 ? source.length : newline + 1;
1066|+    } else if (source.startsWith("/*", index)) {
1067|+      const end = source.indexOf("*/", index + 2);
1068|+      index = end === -1 ? source.length : end + 2;
1069|+    } else {
1070|+      break;
1071|+    }
1072|+  }
1073|+  return index;
1074|+}
1075|+
1076|+function branchBody(source: string, start: number): { body: string; end: number } {
1077|+  const bodyStart = skipTrivia(source, start);
1078|+  if (source[bodyStart] === "{") {
1079|+    const end = closingDelimiter(source, bodyStart, "{", "}");
1080|+    return { body: source.slice(bodyStart + 1, end), end: end + 1 };
1081|+  }
1082|+
1083|+  const end = source.indexOf(";", bodyStart);
1084|+  const statementEnd = end === -1 ? source.length : end + 1;
1085|+  return { body: source.slice(bodyStart, statementEnd), end: statementEnd };
1086|+}
