1088|+function tierBranchLines(): string[] {
1089|+  return SOURCE_ROOTS.flatMap((sourceRoot) =>
1090|+    sourceFiles(join(PROJECT_ROOT, sourceRoot)).flatMap((absolutePath) => {
1091|+      const projectPath = relative(PROJECT_ROOT, absolutePath).split(sep).join("/");
1092|+      if (projectPath === "packages/contract/src/plan-tiers.ts") return [];
1093|+
1094|+      const source = readFileSync(absolutePath, "utf8");
1095|+      const selectors = rosterSelectors(source);
1096|+      const hits: string[] = [];
1097|+      const location = (index: number) =>
1098|+        `${projectPath}:${source.slice(0, index).split("\n").length}`;
1099|+      const controlFlow = /\b(if|switch)\s*\(/g;
1100|+      for (const match of source.matchAll(controlFlow)) {
1101|+        const opening = source.indexOf("(", match.index);
1102|+        const closing = closingDelimiter(source, opening, "(", ")");
1103|+        const condition = source.slice(opening + 1, closing);
1104|+        if (!/\b(?:plan_tier|planTier)\b/.test(condition)) continue;
1105|+
1106|+        const consequent = branchBody(source, closing + 1);
1107|+        let selectedBody = consequent.body;
1108|+        if (match[1] === "if") {
1109|+          const afterConsequent = skipTrivia(source, consequent.end);
1110|+          if (source.startsWith("else", afterConsequent)) {
1111|+            selectedBody += branchBody(source, afterConsequent + 4).body;
1112|+          }
1113|+        }
1114|+        const branchSelectsRoster = selectsRoster(selectedBody, selectors);
1115|+        const selectsTierCase = match[1] !== "switch" ||
1116|+          /\bcase\s+(?:"(?:free|premium)"|'(?:free|premium)')\s*:/.test(selectedBody);
1117|+        if (branchSelectsRoster && selectsTierCase) hits.push(location(match.index));
1118|+      }
1119|+
1120|+      const tierTernary = /\b(?:plan_tier|planTier)\b[^;?]*\?[^;]*;/gs;
1121|+      for (const match of source.matchAll(tierTernary)) {
1122|+        if (selectsRoster(match[0], selectors)) hits.push(location(match.index));
1123|+      }
1124|+      return [...new Set(hits)];
1125|+    })
1126|+  ).sort();
